export function createOptimisticStore(initialState) {
  let baseState = initialState;
  let pendingChanges = [];
  let listeners = [];
  let visibleState = initialState;

  function notifyListeners() {
    listeners.forEach(listener => {
      try {
        listener();
      } catch (e) {
        // Swallow errors to ensure all listeners are notified
      }
    });
  }

  function getState() {
    return visibleState;
  }

  function apply(id, update) {
    if (pendingChanges.some(change => change.id === id)) {
      throw new Error(`Change with id ${id} already exists`);
    }

    let newVisibleState;
    try {
      newVisibleState = update(visibleState);
    } catch (error) {
      throw error;
    }

    pendingChanges.push({ id, update });
    visibleState = newVisibleState;
    notifyListeners();
  }

  function confirm(id) {
    const index = pendingChanges.findIndex(change => change.id === id);
    if (index === -1) {
      return false;
    }

    const { update } = pendingChanges[index];
    pendingChanges.splice(index, 1);
    baseState = update(baseState);

    visibleState = pendingChanges.reduce((state, change) => change.update(state), baseState);
    notifyListeners();
    return true;
  }

  function rollback(id) {
    const index = pendingChanges.findIndex(change => change.id === id);
    if (index === -1) {
      return false;
    }

    pendingChanges.splice(index, 1);
    visibleState = pendingChanges.reduce((state, change) => change.update(state), baseState);
    notifyListeners();
    return true;
  }

  function subscribe(listener) {
    listeners.push(listener);
    return function unsubscribe() {
      listeners = listeners.filter(l => l !== listener);
    };
  }

  return {
    getState,
    apply,
    confirm,
    rollback,
    subscribe
  };
}
